#!/usr/bin/env node
// Generates platform token files from design/tokens.json and copies the
// bundled display fonts into both apps. Fails if any text/background pair
// listed in `contrastChecks` is below WCAG AA (4.5:1) in either theme.
//
//   node design/generate-tokens.mjs           # write files
//   node design/generate-tokens.mjs --check   # verify generated files are up to date

import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = JSON.parse(readFileSync(join(root, "design/tokens.json"), "utf8"));
const checkOnly = process.argv.includes("--check");

const KOTLIN_OUT = join(root, "android/core/designsystem/src/main/kotlin/com/thinkofme/core/designsystem/theme/Tokens.kt");
const SWIFT_OUT = join(root, "ios/Packages/DesignSystem/Sources/DesignSystem/Generated/Tokens.swift");
const ANDROID_FONTS = join(root, "android/core/designsystem/src/main/res/font");
const IOS_FONTS = join(root, "ios/Packages/DesignSystem/Sources/DesignSystem/Resources/Fonts");

// ---------- contrast ----------
function luminance(hex) {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((c) =>
    c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4,
  );
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}
const failures = [];
for (const theme of ["light", "dark"]) {
  for (const [fg, bg] of tokens.contrastChecks) {
    const ratio = contrast(tokens.color[theme][fg], tokens.color[theme][bg]);
    if (ratio < 4.5) failures.push(`${theme}: ${fg} on ${bg} = ${ratio.toFixed(2)}:1`);
  }
}
if (failures.length) {
  console.error("Contrast check failed (needs 4.5:1):\n  " + failures.join("\n  "));
  process.exit(1);
}

// ---------- shared ----------
const colorKeys = Object.keys(tokens.color.light);
const header = "GENERATED by design/generate-tokens.mjs from design/tokens.json. Do not edit by hand.";
const hex = (value) => value.replace("#", "").toUpperCase();
const camel = (s) => s[0].toUpperCase() + s.slice(1);
const weightName = { 400: "Normal", 500: "Medium", 600: "SemiBold", 700: "Bold" };
const swiftWeight = { 400: ".regular", 500: ".medium", 600: ".semibold", 700: ".bold" };

// ---------- Kotlin ----------
const kotlin = `// ${header}
@file:Suppress("MagicNumber")

package com.thinkofme.core.designsystem.theme

import androidx.compose.runtime.Immutable
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

@Immutable
data class AppColors(
${colorKeys.map((k) => `    val ${k}: Color,`).join("\n")}
    val isDark: Boolean,
)

${["light", "dark"].map((theme) => `val ${camel(theme)}AppColors = AppColors(
${colorKeys.map((k) => `    ${k} = Color(0xFF${hex(tokens.color[theme][k])}),`).join("\n")}
    isDark = ${theme === "dark"},
)`).join("\n\n")}

val PersonHues: List<Color> = listOf(
${tokens.personHues.map((h) => `    Color(0xFF${hex(h)}),`).join("\n")}
)

@Immutable
data class AppTypeSpec(
    val size: TextUnit,
    val lineHeight: TextUnit,
    val weight: FontWeight,
    val isDisplay: Boolean,
    val tracking: TextUnit,
)

object AppTypeScale {
${Object.entries(tokens.type).map(([name, t]) => `    val ${name} = AppTypeSpec(${t.size}.sp, ${t.lineHeight}.sp, FontWeight.${weightName[t.weight]}, ${t.family === "display"}, ${t.tracking}.sp)`).join("\n")}
}

object AppSpace {
${Object.entries(tokens.space).map(([k, v]) => `    val ${k} = ${v}.dp`).join("\n")}
}

object AppRadius {
${Object.entries(tokens.radius).map(([k, v]) => `    val ${k} = ${v}.dp`).join("\n")}
}

object AppMotion {
    const val QUICK_MS = ${tokens.motion.quickMs}
    const val STANDARD_MS = ${tokens.motion.standardMs}
    const val EMPHASIZED_MS = ${tokens.motion.emphasizedMs}
    const val SPRING_RESPONSE = ${tokens.motion.springResponse}f
    const val SPRING_DAMPING = ${tokens.motion.springDamping}f
    const val BOUNCY_RESPONSE = ${tokens.motion.bouncyResponse}f
    const val BOUNCY_DAMPING = ${tokens.motion.bouncyDamping}f
}
`;

// ---------- Swift ----------
const swift = `// ${header}

import CoreGraphics
import SwiftUI

public struct AppPalette: Sendable {
${colorKeys.map((k) => `    public let ${k}: UInt32`).join("\n")}
}

public struct AppTypeSpec: Sendable {
    public let size: CGFloat
    public let lineHeight: CGFloat
    public let weight: Font.Weight
    public let isDisplay: Bool
    public let tracking: CGFloat
}

public enum AppTokens {
${["light", "dark"].map((theme) => `    public static let ${theme} = AppPalette(
${colorKeys.map((k, i) => `        ${k}: 0x${hex(tokens.color[theme][k])}${i < colorKeys.length - 1 ? "," : ""}`).join("\n")}
    )`).join("\n\n")}

    public static let personHues: [UInt32] = [${tokens.personHues.map((h) => `0x${hex(h)}`).join(", ")}]

    public enum TypeScale {
${Object.entries(tokens.type).map(([name, t]) => `        public static let ${name} = AppTypeSpec(size: ${t.size}, lineHeight: ${t.lineHeight}, weight: ${swiftWeight[t.weight]}, isDisplay: ${t.family === "display"}, tracking: ${t.tracking})`).join("\n")}
    }

    public enum Space {
${Object.entries(tokens.space).map(([k, v]) => `        public static let ${k}: CGFloat = ${v}`).join("\n")}
    }

    public enum Radius {
${Object.entries(tokens.radius).map(([k, v]) => `        public static let ${k}: CGFloat = ${v}`).join("\n")}
    }

    public enum Motion {
        public static let quick: Double = ${tokens.motion.quickMs / 1000}
        public static let standard: Double = ${tokens.motion.standardMs / 1000}
        public static let emphasized: Double = ${tokens.motion.emphasizedMs / 1000}
        public static let springResponse: Double = ${tokens.motion.springResponse}
        public static let springDamping: Double = ${tokens.motion.springDamping}
        public static let bouncyResponse: Double = ${tokens.motion.bouncyResponse}
        public static let bouncyDamping: Double = ${tokens.motion.bouncyDamping}
    }

    public enum FontFile {
${Object.entries(tokens.fonts).map(([script, file]) => `        public static let ${script} = "${file}"`).join("\n")}
    }
}
`;

// ---------- write / check ----------
let stale = false;
function emit(path, content) {
  if (checkOnly) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) {
      console.error(`Out of date: ${path}`);
      stale = true;
    }
    return;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`wrote ${path.replace(root + "/", "")}`);
}
emit(KOTLIN_OUT, kotlin);
emit(SWIFT_OUT, swift);

if (!checkOnly) {
  mkdirSync(ANDROID_FONTS, { recursive: true });
  mkdirSync(IOS_FONTS, { recursive: true });
  for (const file of Object.values(tokens.fonts)) {
    copyFileSync(join(root, "design/fonts", `${file}.ttf`), join(ANDROID_FONTS, `${file}.ttf`));
    copyFileSync(join(root, "design/fonts", `${file}.ttf`), join(IOS_FONTS, `${file}.ttf`));
  }
  console.log("copied fonts");
}
if (stale) {
  console.error("Run: node design/generate-tokens.mjs");
  process.exit(1);
}
